var dir = "/home/andr/WORK/GAGG/DynamicPET/Out10M_90deg"

var fn = dir + "/" + "SensorSignals.txt"
var sensSigs = core.loadNumericArray(fn)
var numEv = sensSigs.length
if (numEv == 0) core.abort("There are no events!")
core.print("Loaded", numEv, "events")

var sensSig1 = []; sensSig1.length = numEv
var sensSig2 = []; sensSig2.length = numEv
for (var iEv = 0; iEv < numEv; iEv++)
{
    sensSig1[iEv] = []; sensSig1[iEv].length = 64
    sensSig2[iEv] = []; sensSig2[iEv].length = 64
    for (var iS = 0; iS < 64; iS++)
    {
        sensSig1[iEv][iS] = sensSigs[iEv][iS]
        sensSig2[iEv][iS] = sensSigs[iEv][iS+64]
    }
}

response.loadResponseModel("/home/andr/WORK/GAGG/100kNoGains/axial3d.json")
mercury.newReconstructor("ML", 15)
mercury.setCutoffRadius(40)
mercury.configure_COG(0, 0.99, 0)
mercury.configure_statistical(true, true, 0);

core.print("Staring reconstruction: First camera");
var start = core.getTimeMarkMilliseconds()
mercury.reconstructEvents(sensSig1)
var stop = core.getTimeMarkMilliseconds()
core.print("  Elapsed time:", stop-start, "ms")
var recPosE1 = mercury.getRecXYZE()
var stat1 = mercury.getRecStats()

core.print("Staring reconstruction: Second camera");
start = core.getTimeMarkMilliseconds()
mercury.reconstructEvents(sensSig2)
stop = core.getTimeMarkMilliseconds()
core.print("  Elapsed time:", stop-start, "ms")
var recPosE2 = mercury.getRecXYZE()
var stat2 = mercury.getRecStats()

hist.new1D("e1", 1000, 0, 1.5)
hist.new1D("e2", 1000, 0, 1.5)

hist.new1D("chi2_1", 1000, 0, 3)
hist.new1D("chi2_2", 1000, 0, 3)

var coinc = []
var zOffset = 0.5*geo.getGeoConstValue("GapCameras") + geo.getGeoConstValue("SurfToScintMid")
for (var iEv = 0; iEv < numEv; iEv++)
{
    var e1 = recPosE1[iEv][3]
    hist.fill("e1", e1, 1)
    var e2 = recPosE2[iEv][3]
    hist.fill("e2", e2, 1)

    var chi2_1 = stat1[iEv][1]
    var chi2_2 = stat2[iEv][1]
    hist.fill("chi2_1", chi2_1, 1)
    hist.fill("chi2_2", chi2_2, 1)

    if ( (e1 > 0.85 && e1 < 1.15) && (e2 > 0.85 && e2 < 1.15) )
        if ( chi2_1 < 2 && chi2_2 < 2)
        {
            var x1 = recPosE1[iEv][0]
            var y1 = recPosE1[iEv][1]
            var z1 = recPosE1[iEv][2]

            var x2 =  recPosE2[iEv][0]
            var y2 = -recPosE2[iEv][1]
            var z2 = -recPosE2[iEv][2]

            coinc.push([iEv, x1, y1, z1, x2, y2, z2])
        }
}

core.print("Coincidences:", coinc.length)
core.print("First one:", coinc[0])

core.saveArray(coinc, dir + "/coinc.txt")

hist.draw("e1", "hist")
hist.draw("e2", "histsame"); grwin.addToBasket("Rec energy")
hist.draw("chi2_1", "hist")
hist.draw("chi2_2", "histsame"); grwin.addToBasket("Rec chi2")

var ScannerName = "MercuryPET"

var CrystalXY = 1
var CrystalZ  = 1

// assume first camera below, no rotation, with z_offset = -0.5*GapCameras - SurfToScintMid
//        second camera above, flip inverting y and z (-z_offset)
var zOffset = 0.5*geo.getGeoConstValue("GapCameras") + geo.getGeoConstValue("SurfToScintMid")
//core.print(zOffset)

var RangeXY = 2 * geo.getGeoConstValue("Range")
var RangeZ  =     geo.getGeoConstValue("ScintZ")

var numXY = math.ceil(RangeXY / CrystalXY)
var numZ  = math.ceil(RangeZ  / CrystalZ)
core.print("Num scint in X and Y direction:", numXY)
core.print("Num scint in Z direction:", numZ)

var numCryst = 2 * numXY * numXY * numZ

core.print("Making a PET scanner (", ScannerName, ") with the total number of crystals of", numCryst)

var crystArray = []; crystArray.length = numCryst

// bot then up, increasing indeces in ALL directions:
// X -->
// Y -->
// Z -->
var iScint = 0
for (var iCam = 0; iCam < 2; iCam++)
{
    for (var iX = 0; iX < numXY; iX++)
    {
        var x = -CrystalXY * 0.5*(numXY-1) + iX * CrystalXY
        for (var iY = 0; iY < numXY; iY++)
        {
            var y = -CrystalXY * 0.5*(numXY-1) + iY * CrystalXY
            for (var iZ = 0; iZ < numZ; iZ++)
            {
                var z = -CrystalZ * 0.5*(numZ-1) + iZ * CrystalZ + (iCam == 0 ? -zOffset : zOffset)
                crystArray[iScint] = [x,y,z, 0,0,(iCam == 0 ? 1 : -1.0)] // x y x  dx,dy,dz
                iScint++
            }
        }
    }
}

pet.createScanner(ScannerName, 30, 1, 1, 10, crystArray)

var dir = "/home/andr/WORK/GAGG/DynamicPET/OutCombined"
core.saveArray(crystArray, dir + "/crArray.txt")

//var dir = "/home/andr/WORK/GAGG/DynamicPET/Out10M_0deg"
var dir = "/home/andr/WORK/GAGG/DynamicPET/Out10M_90deg"

var coinc = core.loadNumericArray(dir + "/coinc.txt")

var size = coinc.length
core.print("Available coincedences:", size)
if (size == 0) core.abort("")

var pairs = []

function isBad(iX, iY, iZ)
{
    if (iX < 0 || iX >= numXY) return true
    if (iY < 0 || iY >= numXY) return true
    if (iZ < 0 || iZ >= numZ)  return true
    return false
}

var offset = numXY * numXY * numZ
for (var iP = 0; iP < size; iP++)
{
    var thisCoinc = coinc[iP]

    var iEv = thisCoinc[0]
    core.print("-->", iEv)

    var x1 = thisCoinc[1]
    var y1 = thisCoinc[2]
    var z1 = thisCoinc[3]

    var x2 = thisCoinc[4]
    var y2 = thisCoinc[5]
    var z2 = thisCoinc[6]

    var iX1 = Math.round(x1 / CrystalXY + 0.5*(numXY - 1))
    var iY1 = Math.round(y1 / CrystalXY + 0.5*(numXY - 1))
    var iZ1 = Math.round(z1 / CrystalZ  + 0.5*(numZ  - 1))
    core.print("  ", [x1, y1, z1], [iX1, iY1, iZ1])

    var iX2 = Math.round(x2 / CrystalXY + 0.5*(numXY - 1))
    var iY2 = Math.round(y2 / CrystalXY + 0.5*(numXY - 1))
    var iZ2 = Math.round(z2 / CrystalZ  + 0.5*(numZ  - 1))
    core.print("  ", [x2, y2, z2], [iX2, iY2, iZ2])

    if (isBad(iX1, iY1, iZ1)) continue
    if (isBad(iX2, iY2, iZ2)) continue

    var iScint1 = iX1 * (numXY*numZ) + iY1 * numZ + iZ1
    var iScint2 = iX2 * (numXY*numZ) + iY2 * numZ + iZ2 + offset

    core.print("  ", iScint1, iScint2 )

    pairs.push([iScint1, iScint2])

    if (iScint1 < 0) core.abort("")
}

core.print("Good coincidences:", pairs.length)

pet.directSaveCoincideneData(pairs, ScannerName, dir, "petDataHeader.h", "petDataBinary.bin")

