        var iZ2 = Math.round(z2 / CrystalZ  + 0.5*(numZ  - 1))
        core.print("  ", [x2, y2, z2], [iX2, iY2, iZ2])

        if (isBad(iX1, iY1, iZ1)) continue
        if (isBad(iX2, iY2, iZ2)) continue

        var iScint1 = iX1 * (numXY*numZ) + iY1 * numZ + iZ1
        var iScint2 = iX2 * (numXY*numZ) + iY2 * numZ + iZ2 + offset

        core.print("  ", iScint1, iScint2, timeStamp+1) // time in ms!

        outputAr.push([iScint1, iScint2, (timeStamp+1)*1e6]) // time in ns as in the writer there is ns->ms conversion
    }

    timeStamp += timeDelta
}

core.print("Good coincidences:", outputAr.length)
